  v.vehicleNotes = o.vehicleNotes.map((x) => exportAiUnitRef(x, cx));
  v.command = exportCommandIn(o.command, cx);
  v.lastCommand = ((x) => (x === null || x === undefined ? x : exportSquadCommand(x, cx)))(o.lastCommand);
  v.secondaryWaitUntil = o.secondaryWaitUntil;
  v.reboardAt = o.reboardAt;
  v.roll = o.roll;
  v.homeFacing = o.homeFacing;
  v.homeDirection = o.homeDirection.clone();
  v.processed = o.processed;
  v.lodSkipped = o.lodSkipped;
